use super::*;
use crate::{DslValue,retained_clone::{RetainedCloneSource,RetainedClone,RetainedCloneCursor},source_fixture::{Wallet,receive,post_step,close_owned,denials}};
const BODY:usize=32768;
fn law()->serde_json::Value{serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🗂️map/📐️.json")).unwrap()}
fn source<T:RetireOwned+Sync>(value:T,bank:&mut Wallet)->RetainedCloneSource<T>{crate::source_fixture::capture(value,bank,|w|w.loan(1,BODY),|w|w.work_remaining(),|w,p,work,h,g|w.post(p,work,g,h))}
fn heap<T>(f:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(f)}
fn close<I:NativeValueSource+?Sized>(r:&mut NativeMapReceiver<I,String>,bank:&mut Wallet){let g=bank.loan(1,BODY);let q=r.begin_close_work_demand().unwrap();assert!(q<=bank.work_remaining());let(t,h)=heap(||r.begin_close_step(g,q));post_step(bank,t,g,h,|e|panic!("unexpected close-intent refusal: {e:?}")).unwrap();let mut actual=None;for _ in 0..100000{if r.terminal_is_empty()&&actual.is_none(){return}let d=crate::source_fixture::close_demands(&actual,r.close_demands(BODY)).unwrap();let g=bank.loan(1,BODY);for denied in denials(g,d){let(t,h)=heap(||crate::source_fixture::close_step(&mut actual,denied,bank.work_remaining(),r.close_demands(BODY),r.close_work_demand(BODY),|g,a|r.close_step(g,a)));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(crate::source_fixture::close_demands(&actual,r.close_demands(BODY)).unwrap(),d)}let(t,h)=heap(||crate::source_fixture::close_step(&mut actual,g,bank.work_remaining(),r.close_demands(BODY),r.close_work_demand(BODY),|g,a|r.close_step(g,a)));post_step(bank,t,g,h,|e|e.retained_progress()).unwrap();}panic!("native map closure stalled")}
#[test]fn original_map_receiving_matches_fixture_and_closes_every_partial_owner(){let law=law();for case in law["cases"].as_array().unwrap(){for cut in law["cancelCuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).chain(std::iter::once(100000)){let mut bank=Wallet::from_profile(&law["stock"]);let make=||DslValue::Object(case["entries"].as_array().unwrap().iter().map(|e|(e[0].as_str().unwrap().into(),DslValue::String(e[1].as_str().unwrap().into()))).collect());let s=source(make(),&mut bank);let foreign=source(make(),&mut bank);let(mut r,h)=heap(<OrderedMap<String>as NativeReceive<DslValue>>::receiver);assert_eq!(h,(0,0));let mut callback=|_|true;let mut c=NativeDecodeControl::new(1<<26,&mut callback);for _ in 0..cut{if r.output_ready(){break}let d=r.demands(s.borrow(),BODY,bank.work_remaining()).unwrap();assert!(d.copy_bytes<=BODY);let g=bank.loan(1,BODY);for denied in denials(g,d){let(t,h)=heap(||receive(&mut c,denied,bank.work_loan(bank.work_remaining()),|c|{let maximum=c.available_work_units().unwrap();r.advance(s.borrow(),c,BODY,maximum,denied)}));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.demands(s.borrow(),BODY,bank.work_remaining()).unwrap(),d)}let(t,h)=heap(||receive(&mut c,g,bank.work_loan(bank.work_remaining()),|c|{let maximum=c.available_work_units().unwrap();r.advance(s.borrow(),c,BODY,maximum,g)}));post_step(&mut bank,t,g,h,crate::OriginalReceivingPrimary::retained_progress).unwrap();assert!(r.demands(foreign.borrow(),BODY,bank.work_remaining()).is_err())}if r.output_ready(){let g=bank.loan(1,BODY);let(t,h)=heap(||r.take(g));let(map,p)=t.result.unwrap().unwrap();bank.post(p,t.work,g,h);let entries:Vec<_>=map.iter().map(|(k,v)|serde_json::json!([k,v])).collect();assert_eq!(serde_json::Value::Array(entries),case["expected"]);close_owned(map,&mut bank,BODY,100000)}else{assert_ne!(cut,100000,"actual map preparation stalled")}close(&mut r,&mut bank);close_owned(s,&mut bank,BODY,100000);close_owned(foreign,&mut bank,BODY,100000);}}}
fn alias_post(bank:&mut Wallet,turn:crate::OriginalRetirementOutcome,g:RetainedCloneGrant,h:(usize,usize))->Result<RetainedCloneStep,crate::OriginalRetirementFailure>{assert!(turn.work<=bank.work_remaining());let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());bank.post(p,turn.work,g,h);turn.result}
#[test]fn ordered_map_original_alias_clone_keeps_its_root_and_closes_all_denied_prefixes(){let alias:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../🗂️ordered/🧬️alias.json")).unwrap();for cut in alias["cancelCuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).chain(std::iter::once(100)){let mut bank=Wallet::from_profile(&law()["stock"]);let map:OrderedMap<String>=alias["entries"].as_array().unwrap().iter().map(|v|(v[0].as_str().unwrap().to_owned(),v[1].as_str().unwrap().to_owned())).collect();let identity=map.original_root_identity();let s=source(map,&mut bank);let mut cursor=OrderedMap::<String>::retained_clone_cursor();let mut actual=None;for _ in 0..cut{if cursor.output_ready()&&actual.is_none(){break}let d=crate::source_fixture::close_demands(&actual,cursor.advance_demands(s.borrow(),4096,bank.work_remaining())).unwrap();assert!(d.copy_bytes<=4096);let g=bank.loan(1,4096);for denied in denials(g,d){let(t,h)=heap(||crate::source_fixture::close_step(&mut actual,denied,bank.work_remaining(),cursor.advance_demands(s.borrow(),4096,bank.work_remaining()),cursor.advance_work_demand(s.borrow(),4096,bank.work_remaining()),|g,a|cursor.advance(s.borrow(),4096,bank.work_remaining(),g,a)));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(crate::source_fixture::close_demands(&actual,cursor.advance_demands(s.borrow(),4096,bank.work_remaining())).unwrap(),d)}let(t,h)=heap(||crate::source_fixture::close_step(&mut actual,g,bank.work_remaining(),cursor.advance_demands(s.borrow(),4096,bank.work_remaining()),cursor.advance_work_demand(s.borrow(),4096,bank.work_remaining()),|g,a|cursor.advance(s.borrow(),4096,bank.work_remaining(),g,a)));assert_eq!(h.0,alias["aliasCapacityBytes"].as_u64().unwrap()as usize);alias_post(&mut bank,t,g,h).unwrap();}if cut==100{assert!(cursor.output_ready());let g=bank.loan(1,4096);let(t,h)=heap(||cursor.take(g));let(value,p)=t.result.unwrap().unwrap();bank.post(p,t.work,g,h);assert_eq!(h,(0,0));assert_eq!(value.original_root_identity(),identity);assert!(alias["sharedRoot"].as_bool().unwrap());close_owned(value,&mut bank,BODY,100000)}cursor.begin_close();for _ in 0..100000{if cursor.terminal_is_empty()&&actual.is_none(){break}let d=crate::source_fixture::close_demands(&actual,cursor.close_demands(4096)).unwrap();let g=bank.loan(1,4096);for denied in denials(g,d){let(t,h)=heap(||crate::source_fixture::close_step(&mut actual,denied,bank.work_remaining(),cursor.close_demands(4096),cursor.close_work_demand(4096),|g,a|cursor.close_step(g,a)));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(crate::source_fixture::close_demands(&actual,cursor.close_demands(4096)).unwrap(),d)}let(t,h)=heap(||crate::source_fixture::close_step(&mut actual,g,bank.work_remaining(),cursor.close_demands(4096),cursor.close_work_demand(4096),|g,a|cursor.close_step(g,a)));alias_post(&mut bank,t,g,h).unwrap();}assert!(cursor.terminal_is_empty());close_owned(s,&mut bank,BODY,100000)}}
